param([string]$EnvFile='.\\.env')
$ErrorActionPreference='Stop'
$v=@{};Get-Content $EnvFile|Where-Object{$_-match'^[^#].*='}|ForEach-Object{$p=$_-split'=',2;$v[$p[0].Trim()]=$p[1].Trim()}
foreach($n in @('GK_SITE_URL','GK_UNIFIED_API_TOKEN','GK_CONTROL_TOKEN')){if([string]::IsNullOrWhiteSpace($v[$n])){throw "$n fehlt."}}
$site=$v.GK_SITE_URL.TrimEnd('/');$uh=@{Authorization='Bearer '+$v.GK_UNIFIED_API_TOKEN};$ch=@{Authorization='Bearer '+$v.GK_CONTROL_TOKEN}
function Upload-Svg([string]$filename,[string]$title,[string]$alt,[string]$svg){$payload=@{filename=$filename;title=$title;alt=$alt;svg=$svg}|ConvertTo-Json -Compress;$u=Invoke-RestMethod ($site+'/wp-json/gk-control/v1/media/upload-svg') -Method Post -Headers $ch -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($payload));$id=[long]$(if($u.attachment_id){$u.attachment_id}elseif($u.media_id){$u.media_id}else{$u.id});if($id-le0){throw "SVG-Upload fehlgeschlagen: $filename"};return $id}
function Read-Post([long]$id){Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/read-post') -Method Post -Headers $uh -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes((@{id=$id}|ConvertTo-Json -Compress))) -TimeoutSec 60}
function Save-Post([long]$id,[string]$content){$u=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/update-post') -Method Post -Headers $uh -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes((@{id=$id;content=$content}|ConvertTo-Json -Compress))) -TimeoutSec 60;if($u.updated-ne$true){throw "Update nicht bestaetigt: $id"};$q=Read-Post $id;if(([string]$q.content)-cne$content){throw "Speicherpruefung fehlgeschlagen: $id"}}
function Set-Featured([long]$id,[long]$media){$b=@{post_id=$id;attachment_id=$media}|ConvertTo-Json -Compress;Invoke-RestMethod ($site+'/wp-json/gk-control/v1/media/set-featured') -Method Post -Headers $ch -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($b))|Out-Null}
function Get-Src([string]$tag){return [Net.WebUtility]::HtmlDecode([regex]::Match($tag,'(?is)\\bsrc=["''](?<v>[^"'']+)').Groups['v'].Value)}
function Remove-Duplicate-Figures([string]$html){$seen=@{};$result=$html;$figs=@([regex]::Matches($html,'(?is)<figure\\b[^>]*>.*?</figure>'));foreach($f in $figs){$img=[regex]::Match($f.Value,'(?is)<img\\b[^>]*>');if(-not$img.Success){continue};$src=Get-Src $img.Value;if(-not$src){continue};$key=($src-split'\\?')[0].ToLowerInvariant();if($seen.ContainsKey($key)){$result=$result.Replace($f.Value,'')}else{$seen[$key]=$true}};return $result}

$signalAlt='VDSL-Signalweg: DSLAM oder MSAN als aktives Bauteil im grauen MFG, danach grauer KVz, Kupferkabel, APL, Endleitung, erste TAE und Router.'
$signalSvg=@'
<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630" role="img" aria-labelledby="t d"><title id="t">VDSL-Signalweg mit DSLAM im MFG und KVz</title><desc id="d">Ein graues Multifunktionsgehäuse enthält DSLAM oder MSAN. Von dort führt das Kupfernetz über einen grauen Kabelverzweiger zum APL, zur Endleitung, ersten TAE und zum Router.</desc><rect width="1200" height="630" fill="#f5f7fa"/><text x="55" y="62" font-family="Arial" font-size="36" font-weight="700" fill="#17263a">VDSL: vom MFG bis zum Router</text><g font-family="Arial" text-anchor="middle"><g stroke="#273444" stroke-width="5"><rect x="35" y="155" width="205" height="230" rx="12" fill="#aeb4bb"/><rect x="265" y="155" width="145" height="230" rx="8" fill="#aeb4bb"/><rect x="445" y="190" width="120" height="160" rx="16" fill="#fff"/><rect x="600" y="190" width="145" height="160" rx="16" fill="#fff"/><rect x="780" y="190" width="120" height="160" rx="16" fill="#fff"/><rect x="935" y="190" width="120" height="160" rx="16" fill="#fff"/><rect x="1080" y="190" width="100" height="160" rx="16" fill="#fff"/></g><rect x="65" y="225" width="145" height="95" rx="9" fill="#eef1f4" stroke="#273444" stroke-width="4"/><g fill="#17263a" font-size="20" font-weight="700"><text x="137" y="195">MFG (grau)</text><text x="137" y="265">DSLAM /</text><text x="137" y="294">MSAN</text><text x="337" y="195">KVz (grau)</text><text x="337" y="258">passiver</text><text x="337" y="287">Verteiler</text><text x="505" y="278">APL</text><text x="672" y="258">Endleitung</text><text x="840" y="258">erste</text><text x="840" y="287">TAE</text><text x="995" y="258">DSL-</text><text x="995" y="287">Kabel</text><text x="1130" y="278">Router</text></g><g stroke="#b66a14" stroke-width="8" fill="none"><path d="M240 270h25"/><path d="M410 270h35"/><path d="M565 270h35"/><path d="M745 270h35"/><path d="M900 270h35"/><path d="M1055 270h25"/></g></g><g font-family="Arial" fill="#17263a"><text x="55" y="445" font-size="25" font-weight="700">Fachliche Einordnung</text><text x="55" y="485" font-size="21">Der DSLAM/MSAN ist aktive Technik im MFG – keine separate Station vor dem MFG.</text><text x="55" y="522" font-size="21">Der KVz ist ein eigener passiver Verteilpunkt im Kupfernetz. MFG und KVz sind außen üblicherweise grau.</text><text x="55" y="565" font-size="18" fill="#41566f">Bei ADSL kann die aktive DSL-Technik je nach Ausbau auch in der Vermittlungsstelle stehen.</text></g></svg>
'@
$fiberAlt='FTTH-Glasfaserkabel mit Lichtwellenleiter; kein Koaxial- und kein Kupfer-DSL-Kabel.'
$fiberSvg=@'
<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630" role="img" aria-labelledby="t d"><title id="t">FTTH-Glasfaserkabel</title><desc id="d">Mehrere dünne Lichtwellenleiter mit farbiger Beschichtung in einem Glasfaserkabel. Die Darstellung grenzt Glasfaser eindeutig von Koaxialkabel ab.</desc><rect width="1200" height="630" fill="#f5f9fc"/><text x="55" y="68" font-family="Arial" font-size="38" font-weight="700" fill="#123554">FTTH: Glasfaserkabel statt Koaxialkabel</text><path d="M80 325H720" stroke="#1f2937" stroke-width="150" stroke-linecap="round"/><path d="M115 325H760" stroke="#e7edf3" stroke-width="112" stroke-linecap="round"/><g fill="none" stroke-width="18" stroke-linecap="round"><path d="M145 285H945" stroke="#f5b400"/><path d="M145 315H990" stroke="#e74c3c"/><path d="M145 345H945" stroke="#2e86de"/><path d="M145 375H900" stroke="#2eaf62"/></g><g fill="#fff" stroke="#c9d5df" stroke-width="4"><circle cx="945" cy="285" r="13"/><circle cx="990" cy="315" r="13"/><circle cx="945" cy="345" r="13"/><circle cx="900" cy="375" r="13"/></g><text x="55" y="520" font-family="Arial" font-size="23" fill="#123554">Dünne Lichtwellenleiter übertragen Licht. Es gibt keinen metallischen Innenleiter und kein Koaxialgeflecht.</text><text x="55" y="560" font-family="Arial" font-size="19" fill="#41566f">Vereinfachte technische Darstellung zur eindeutigen Kabelart-Erkennung.</text></svg>
'@
$signalId=Upload-Svg 'gk-dsl-signalweg-mfg-kvz-v3.svg' 'VDSL-Signalweg: DSLAM im MFG, KVz, APL und TAE' $signalAlt $signalSvg
$fiberId=Upload-Svg 'gk-ftth-glasfaserkabel-v1.svg' 'FTTH-Glasfaserkabel korrekt dargestellt' $fiberAlt $fiberSvg
$signal=Invoke-RestMethod ($site+"/wp-json/wp/v2/media/$signalId`?_fields=id,source_url") -TimeoutSec 30;$fiber=Invoke-RestMethod ($site+"/wp-json/wp/v2/media/$fiberId`?_fields=id,source_url") -TimeoutSec 30;$router=Invoke-RestMethod ($site+'/wp-json/wp/v2/media/23278?_fields=id,source_url,alt_text') -TimeoutSec 30
$items=@();foreach($kind in @('posts','pages')){$page=1;do{try{$batch=@(Invoke-RestMethod($site+"/wp-json/wp/v2/$kind`?status=publish&per_page=100&page=$page&_fields=id,slug,title,link")-TimeoutSec 45);if($batch.Count-eq1-and$batch[0]-is[Array]){$batch=@($batch[0])}}catch{if($_.Exception.Response-and[int]$_.Exception.Response.StatusCode-eq400){$batch=@()}else{throw}};foreach($i in$batch){$i|Add-Member kind $kind -Force};$items+=$batch;$page++}while($batch.Count-eq100)}
$root=Split-Path -Parent $PSScriptRoot;$backup=Join-Path $root ('backups\\technician-review-'+(Get-Date -Format yyyyMMdd-HHmmss));$report=Join-Path $root 'reports';New-Item $backup,$report -ItemType Directory -Force|Out-Null;$rows=@()
foreach($item in($items|Sort-Object{[long]$_.id}-Unique)){$id=[long]$item.id;$slug=[string]$item.slug;$title=[Net.WebUtility]::HtmlDecode([string]$item.title.rendered);$post=Read-Post $id;$old=[string]$post.content;$new=$old;$reasons=@()
 $isCoaxTopic=($title-match'(?i)Koax|Kabelanschluss|H.ÜP|DOCSIS');$wrongPattern='(?i)(koax|koax_huep|gkap-dsl-apl-kupfer-hausanschluss)'
 if(-not$isCoaxTopic-and$new-match$wrongPattern){$target=if($title-match'(?i)Router|WLAN|Wi.Fi|Mesh|Repeater|Access Point'){[string]$router.source_url}else{[string]$fiber.source_url};$alt=if($target-eq[string]$router.source_url){'Router als zentraler Punkt für LAN und WLAN im Heimnetz.'}else{$fiberAlt};$replacement='<figure class="gk-article-visual gk-technician-corrected"><img src="'+$target+'" alt="'+[Net.WebUtility]::HtmlEncode($alt)+'" loading="lazy"><figcaption>'+[Net.WebUtility]::HtmlEncode($(if($target-eq[string]$router.source_url){'Router und WLAN im Heimnetz'}else{'FTTH-Glasfaserkabel'}))+'</figcaption></figure>';$new=[regex]::Replace($new,'(?is)<figure\\b[^>]*>.*?<img\\b[^>]*(?:koax|koax_huep|gkap-dsl-apl-kupfer-hausanschluss)[^>]*>.*?</figure>',$replacement);$new=[regex]::Replace($new,'(?is)<img\\b[^>]*(?:koax|koax_huep|gkap-dsl-apl-kupfer-hausanschluss)[^>]*>','<img src="'+$target+'" alt="'+[Net.WebUtility]::HtmlEncode($alt)+'" loading="lazy">');$reasons+='WRONG_COAX_REPLACED';if($target-eq[string]$router.source_url){Set-Featured $id 23278}else{Set-Featured $id $fiberId}}
 if($slug-eq'apl-tae-signalweg'){$new=[regex]::Replace($new,'(?is)<section\\b[^>]*data-gk-dsl-signalweg=["''][^"'']+["''][^>]*>.*?</section>','');$new=[regex]::Replace($new,'(?is)<(?:section|div)\\b[^>]*class=["''][^"'']*(?:object-path|objektpfad)[^"'']*["''][^>]*>.*?</(?:section|div)>','');$correct='<section class="gk-object-path-corrected" data-gk-object-path="mfg-kvz-v3"><h2>Objektpfad bei VDSL/FTTC</h2><figure><img src="'+[string]$signal.source_url+'" alt="'+$signalAlt+'" width="1200" height="630"><figcaption>DSLAM/MSAN im MFG → KVz → Kupferkabel → APL → Endleitung → erste TAE → Router.</figcaption></figure><p><strong>Fachlich korrekt:</strong> Der DSLAM beziehungsweise MSAN ist ein aktives Bauteil im Multifunktionsgehäuse. Vom MFG führt die Kupferstrecke über den Kabelverzweiger (KVz) und das weitere Kupfernetz zum APL des Gebäudes.</p><ol><li><strong>MFG mit DSLAM/MSAN:</strong> stellt das DSL-Signal bereit.</li><li><strong>KVz:</strong> passiver Kabelverzweiger im Kupfernetz.</li><li><strong>APL:</strong> Abschluss des Betreiber-Kupfernetzes am Gebäude.</li><li><strong>Endleitung und erste TAE:</strong> Hausverkabelung bis zum DSL-Anschluss.</li><li><strong>Router:</strong> synchronisiert sein DSL-Modem mit DSLAM/MSAN.</li></ol><p>MFG und KVz sind Straßengehäuse und werden in der Darstellung bewusst grau gezeigt.</p></section>';$new=$correct+$new;$reasons+='DSL_OBJECT_PATH_CORRECTED';Set-Featured $id $signalId}
 if($slug-eq'ftth-anschlussarten-erklaert'){$new=[regex]::Replace($new,'(?is)<figure\\b[^>]*class=["''][^"'']*gk-technician-corrected[^"'']*["''][^>]*>.*?</figure>','');$new='<figure class="gk-article-visual gk-technician-corrected"><img src="'+[string]$fiber.source_url+'" alt="'+$fiberAlt+'" loading="lazy"><figcaption>FTTH verwendet Lichtwellenleiter – kein Koaxialkabel.</figcaption></figure>'+$new;$reasons+='FTTH_FIBER_IMAGE';Set-Featured $id $fiberId}
 if($slug-eq'router-im-keller'){$new=[regex]::Replace($new,'(?is)<figure\\b[^>]*class=["''][^"'']*gk-technician-corrected[^"'']*["''][^>]*>.*?</figure>','');$new='<figure class="gk-article-visual gk-technician-corrected"><img src="'+[string]$router.source_url+'" alt="Router als zentraler Punkt für LAN und WLAN im Heimnetz." loading="lazy"><figcaption>Der Routerstandort beeinflusst die WLAN-Abdeckung im Haus.</figcaption></figure>'+$new;$reasons+='ROUTER_IMAGE';Set-Featured $id 23278}
 if($slug-eq'gf-ap-erklaert'){$dedup=Remove-Duplicate-Figures $new;if($dedup-cne$new){$new=$dedup;$reasons+='DUPLICATE_GF_AP_IMAGE_REMOVED'}}
 if($new-cne$old){[IO.File]::WriteAllText((Join-Path $backup ("post-$id.html")),$old,[Text.UTF8Encoding]::new($false));Save-Post $id $new;$rows+=[pscustomobject]@{id=$id;slug=$slug;title=$title;status='UPDATED_AND_VERIFIED';reason=$reasons-join','};Write-Host("$id $slug UPDATED_AND_VERIFIED")}}
$cache=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/clear-cache') -Method Post -Headers $uh -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes('{}'));if($cache.cache_cleared-ne$true){throw'Cache nicht geleert'}
foreach($slug in @('apl-tae-signalweg','ftth-anschlussarten-erklaert','gf-ap-erklaert','router-im-keller')){$item=$items|Where-Object slug -eq $slug|Select-Object -First 1;if($null-eq$item){throw"Slug fehlt: $slug"};$html=[string](Invoke-WebRequest ([string]$item.link+'?_gk_review='+(Get-Date -Format HHmmssfff)) -UseBasicParsing -TimeoutSec 60).Content;if($html-match'(?i)(koax_huep|gk-symbol-koax|gkap-dsl-apl-kupfer-hausanschluss)'){throw"Falsches Koaxialbild live: $slug"};if($slug-eq'apl-tae-signalweg'){foreach($required in @('DSLAM/MSAN im MFG','KVz','data-gk-object-path="mfg-kvz-v3"')){if($html-notmatch[regex]::Escape($required)){throw"Objektpfad live nicht verifiziert: $required"}}};if($slug-eq'gf-ap-erklaert'){$srcs=@([regex]::Matches($html,'(?is)<img\\b[^>]*>')|ForEach-Object{Get-Src $_.Value}|Where-Object{$_-match'(?i)gf.?ap'});if(@($srcs|Group-Object|Where-Object Count-gt1).Count){throw'Doppeltes Gf-AP-Bild weiterhin live'}};Write-Host("LIVE_VERIFIED $slug")}
$rows|Export-Csv (Join-Path $report ('technician-review-'+(Get-Date -Format yyyyMMdd-HHmmss)+'.csv')) -NoTypeInformation -Encoding UTF8
Write-Host("FERTIG: Aktualisiert=$($rows.Count) | Signalbild=$signalId | Glasfaserbild=$fiberId | Backups=$backup")
